package com.nextaicommerce.platform.marketplace;
import com.nextaicommerce.platform.catalog.CatalogRepository;import org.springframework.jdbc.core.*;import java.util.*;import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class MarketplaceMappingDraftTest {
 @Test void terminalPackQuantityUsesExistingRulesAndBounds(){for(String sku:List.of("IB-MKH-299402-FOLIOS-3xEA","ITEM-299402-3Xea","ITEM-299402-EAx3"))assertThat(MarketplaceMappingDraft.quantity(sku)).isEqualTo(3);for(String sku:List.of("ITEM-299402","ITEM-299402-3x","ITEM-299402-0xEA","ITEM-299402-10001xEA","ITEM-299402-99999999999999xEA"))assertThat(MarketplaceMappingDraft.quantity(sku)).isEqualTo(1);}
 @Test void bundlesDoNotAssignTheWholePackQuantityToAnIndividualComponent(){for(String sku:List.of("IB-2x354920-2x375283-EGGLIFE-4xEA","IB-467936-467928-OZERY-3xEA")){assertThat(MarketplaceMappingDraft.quantity(sku)).isEqualTo(1);assertThat(MarketplaceMappingDraft.unique(sku,List.of(new MarketplaceMappingDraft.Code(UUID.randomUUID(),"One component","467936")))).isNull();}}
 @Test void exactCodeSuggestsOneProductButBarcodeSubstringAndPartialCodeDoNot(){UUID item=UUID.randomUUID();var code=new MarketplaceMappingDraft.Code(item,"Cheese Cheddar","299402");assertThat(MarketplaceMappingDraft.unique("IB-MKH-299402-CHEESE-3xEA",List.of(code)).id()).isEqualTo(item);assertThat(MarketplaceMappingDraft.unique("IB-MKH-299402-3xEA",List.of(new MarketplaceMappingDraft.Code(UUID.randomUUID(),"Mole UPC 850032994026","399644")))).isNull();assertThat(MarketplaceMappingDraft.unique("IB-MKH-299402-3xEA",List.of(new MarketplaceMappingDraft.Code(UUID.randomUUID(),"Other","1299402")))).isNull();}
 @Test void ambiguousCodesRemainUnselectedAndSameProductAliasesAreNotAConflict(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();var first=new MarketplaceMappingDraft.Code(a,"Product A","299402");assertThat(MarketplaceMappingDraft.unique("IB-299402-3xEA",List.of(first,new MarketplaceMappingDraft.Code(b,"Product B","299402")))).isNull();assertThat(MarketplaceMappingDraft.unique("IB-299402-3xEA",List.of(first,new MarketplaceMappingDraft.Code(a,"Product A","000299402"))).id()).isEqualTo(a);}
 @Test void lookupBindsOnlySelectedTenantAndExactTokensAndNeverPublishes(){var jdbc=mock(JdbcTemplate.class);var catalog=mock(CatalogRepository.class);var service=new MarketplaceMappingDraft(jdbc,catalog);UUID tenant=UUID.randomUUID(),item=UUID.randomUUID();when(jdbc.query(anyString(),org.mockito.ArgumentMatchers.<RowMapper<MarketplaceMappingDraft.Code>>any(),any(Object[].class))).thenReturn(List.of(new MarketplaceMappingDraft.Code(item,"Cheese","299402")));when(catalog.pickerImages(tenant,List.of(item))).thenReturn(Map.of());var draft=service.suggest(tenant,"IB-299402-3xEA");assertThat(draft.quantity()).isEqualTo(3);assertThat(draft.product().id()).isEqualTo(item);verify(jdbc).queryForObject(contains("set_config('app.tenant_id'"),eq(String.class),eq(tenant.toString()));var parameters=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).query(contains("i.tenant_id=?"),org.mockito.ArgumentMatchers.<RowMapper<MarketplaceMappingDraft.Code>>any(),parameters.capture());assertThat(parameters.getValue()).startsWith(tenant,tenant).contains("299402").doesNotContain("%299402%");verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void skuCodeDraftIsUnambiguousPreservesLeadingZerosAndExcludesPackCounts(){assertThat(MarketplaceMappingDraft.detectedItemCode("IB-MKH-00339807-PEPPERON-CAPPEL-EAx12")).isEqualTo("00339807");assertThat(MarketplaceMappingDraft.detectedItemCode("IB-MKH-339807-PEPPERON-CAPPEL-EA")).isEqualTo("339807");assertThat(MarketplaceMappingDraft.detectedItemCode("IB-MKH-339807-123456-EAx12")).isNull();assertThat(MarketplaceMappingDraft.detectedItemCode("IB-MKH-PIZZA-EAx12")).isNull();assertThat(MarketplaceMappingDraft.detectedItemCode("IB-2x354920-2x375283-4xEA")).isNull();}

}
